-- Phase 4D: manual, verified customer-payment ledger. No credentials or gateway data are stored.
CREATE TABLE public.booking_payment_records (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES public.celebration_bookings(id) ON DELETE RESTRICT, payment_reference TEXT NOT NULL UNIQUE, idempotency_key TEXT NOT NULL, transaction_type TEXT NOT NULL CHECK(transaction_type IN ('receipt','refund','reversal')), original_payment_id UUID REFERENCES public.booking_payment_records(id) ON DELETE RESTRICT, amount NUMERIC(12,2) NOT NULL CHECK(amount>0), currency TEXT NOT NULL DEFAULT 'INR', payment_method TEXT CHECK(payment_method IN ('cash','upi','bank_transfer','card_external','other')), external_reference TEXT CHECK(external_reference IS NULL OR char_length(external_reference)<=200), payment_date TIMESTAMPTZ NOT NULL, status TEXT NOT NULL DEFAULT 'recorded' CHECK(status='recorded'), notes TEXT CHECK(notes IS NULL OR char_length(notes)<=2000), recorded_by UUID NOT NULL REFERENCES public.admins(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK((transaction_type='receipt')=(original_payment_id IS NULL)), CHECK((transaction_type='receipt') OR payment_method IS NULL));
CREATE UNIQUE INDEX booking_payment_idempotency_unique ON public.booking_payment_records(booking_id,idempotency_key);
CREATE TABLE public.booking_payment_activities(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),payment_id UUID NOT NULL REFERENCES public.booking_payment_records(id) ON DELETE RESTRICT,event_type TEXT NOT NULL CHECK(event_type IN ('recorded','refunded','reversed')),actor_id UUID REFERENCES public.admins(id) ON DELETE SET NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX booking_payment_records_booking_idx ON public.booking_payment_records(booking_id,payment_date DESC); CREATE INDEX booking_payment_activities_payment_idx ON public.booking_payment_activities(payment_id,created_at DESC);
ALTER TABLE public.booking_payment_records ENABLE ROW LEVEL SECURITY; ALTER TABLE public.booking_payment_activities ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.booking_payment_records,public.booking_payment_activities FROM PUBLIC,anon,authenticated; GRANT ALL ON public.booking_payment_records,public.booking_payment_activities TO service_role;
CREATE OR REPLACE FUNCTION public.booking_payment_summary(p_booking_id UUID) RETURNS TABLE(booking_total NUMERIC,gross_received NUMERIC,total_refunded NUMERIC,total_reversed NUMERIC,net_received NUMERIC,outstanding_balance NUMERIC,payment_status TEXT) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT b.quoted_total,COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type='receipt'),0),COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type='refund'),0),COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type='reversal'),0),COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type='receipt'),0)-COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type IN('refund','reversal')),0),b.quoted_total-(COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type='receipt'),0)-COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type IN('refund','reversal')),0)),CASE WHEN COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type='receipt'),0)-COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type IN('refund','reversal')),0)=0 THEN 'unpaid' WHEN COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type='receipt'),0)-COALESCE(sum(p.amount)FILTER(WHERE p.transaction_type IN('refund','reversal')),0)>=b.quoted_total THEN 'paid' ELSE 'partially_paid' END FROM public.celebration_bookings b LEFT JOIN public.booking_payment_records p ON p.booking_id=b.id WHERE b.id=p_booking_id GROUP BY b.id $$;
CREATE OR REPLACE FUNCTION public.record_admin_booking_payment(p_booking_id UUID,p_idempotency_key TEXT,p_amount NUMERIC,p_currency TEXT,p_method TEXT,p_external_reference TEXT,p_payment_date TIMESTAMPTZ,p_notes TEXT,p_admin_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v public.celebration_bookings%ROWTYPE; v_id UUID; v_net NUMERIC; BEGIN SELECT * INTO v FROM public.celebration_bookings WHERE id=p_booking_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found' USING ERRCODE='P0002'; END IF; IF v.status IN('pending_confirmation','cancelled') THEN RAISE EXCEPTION 'Booking is not eligible for payments' USING ERRCODE='22023'; END IF; IF p_amount<=0 OR p_currency<>v.currency OR p_method NOT IN('cash','upi','bank_transfer','card_external','other') OR NULLIF(btrim(p_idempotency_key),'') IS NULL THEN RAISE EXCEPTION 'Invalid payment details' USING ERRCODE='22023'; END IF; SELECT net_received INTO v_net FROM public.booking_payment_summary(p_booking_id); IF v_net+p_amount>v.quoted_total THEN RAISE EXCEPTION 'Payment exceeds outstanding balance' USING ERRCODE='22023'; END IF; INSERT INTO public.booking_payment_records(booking_id,payment_reference,idempotency_key,transaction_type,amount,currency,payment_method,external_reference,payment_date,notes,recorded_by) VALUES(p_booking_id,'RCPT-'||upper(substr(gen_random_uuid()::text,1,12)),p_idempotency_key,'receipt',p_amount,p_currency,p_method,NULLIF(btrim(p_external_reference),''),p_payment_date,NULLIF(btrim(p_notes),''),p_admin_id) RETURNING id INTO v_id; INSERT INTO public.booking_payment_activities(payment_id,event_type,actor_id,metadata) VALUES(v_id,'recorded',p_admin_id,jsonb_build_object('amount',p_amount,'currency',p_currency)); RETURN v_id; EXCEPTION WHEN unique_violation THEN SELECT id INTO v_id FROM public.booking_payment_records WHERE booking_id=p_booking_id AND idempotency_key=p_idempotency_key; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.booking_payment_summary(UUID),public.record_admin_booking_payment(UUID,TEXT,NUMERIC,TEXT,TEXT,TEXT,TIMESTAMPTZ,TEXT,UUID) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.booking_payment_summary(UUID),public.record_admin_booking_payment(UUID,TEXT,NUMERIC,TEXT,TEXT,TEXT,TIMESTAMPTZ,TEXT,UUID) TO service_role;
